-- Expand-only in-app notifications. Old servers do not read this table.
-- Roll the app back to the previous SHA and leave the table in place.
-- Dropping notifications must be a new forward migration
-- (docs/Cardhub/development-backlog.md §1.3). Do not edit this file after it
-- lands on main. This migration does not alter existing tables.
-- CreateEnum
CREATE TYPE "NotificationType" AS ENUM ('TOPIC_REPLY', 'COMMENT_REPLY', 'MENTION', 'CONTENT_RESOLVED');

-- CreateEnum
CREATE TYPE "NotificationAction" AS ENUM ('MARK_RESOLVED', 'REMOVE_TARGET');

-- CreateEnum
CREATE TYPE "NotificationTargetType" AS ENUM ('LISTING', 'TOPIC', 'REPLY', 'COMMENT');

-- CreateTable
CREATE TABLE "notifications" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "actorId" TEXT,
    "type" "NotificationType" NOT NULL,
    "action" "NotificationAction",
    "targetType" "NotificationTargetType" NOT NULL,
    "targetId" TEXT NOT NULL,
    "excerpt" TEXT NOT NULL,
    "href" TEXT,
    "readAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "notifications_pkey" PRIMARY KEY ("id")
);

-- excerpt is captured at write time and capped at 80 characters.
ALTER TABLE "notifications"
  ADD CONSTRAINT "notifications_excerpt_length_check"
  CHECK (char_length("excerpt") <= 80);

-- CONTENT_RESOLVED carries MARK_RESOLVED or REMOVE_TARGET. Other types do not.
ALTER TABLE "notifications"
  ADD CONSTRAINT "notifications_action_matches_type_check"
  CHECK (
    ("type" = 'CONTENT_RESOLVED' AND "action" IS NOT NULL)
    OR ("type" <> 'CONTENT_RESOLVED' AND "action" IS NULL)
  );

